const menu = document.querySelector('#menu');
const nav = document.querySelector('#nav');
menu.addEventListener('click', () => { const expanded = menu.getAttribute('aria-expanded') !== 'true'; menu.setAttribute('aria-expanded', String(expanded)); nav.classList.toggle('open', expanded); });
nav.querySelectorAll('a').forEach(link => link.addEventListener('click', () => { nav.classList.remove('open'); menu.setAttribute('aria-expanded', 'false'); }));
document.addEventListener('keydown', event => { if (event.key === 'Escape' && menu.getAttribute('aria-expanded') === 'true') { nav.classList.remove('open'); menu.setAttribute('aria-expanded', 'false'); menu.focus(); } });
let reserved = 0;
const status = document.querySelector('#demo-status');
function updateInventory() { document.querySelector('#reserved').textContent = reserved; document.querySelector('#available').textContent = 5 - reserved; document.querySelectorAll('.inventory-bar i').forEach((unit, i) => unit.classList.toggle('reserved', i < reserved)); }
document.querySelector('#reserve-form').addEventListener('submit', event => { event.preventDefault(); const quantity = Number(document.querySelector('#quantity').value); if (!Number.isInteger(quantity) || quantity < 1 || quantity > 5) { status.textContent = 'Elige una cantidad entera entre 1 y 5.'; return; } if (quantity > 5 - reserved) { status.textContent = `No hay disponibilidad suficiente. Puedes apartar ${5 - reserved} unidades más.`; return; } reserved += quantity; updateInventory(); status.textContent = `Apartado confirmado: ${quantity} ${quantity === 1 ? 'unidad' : 'unidades'}. La existencia física sigue en 5; quedan ${5 - reserved} disponibles.`; });
document.querySelector('#reset').addEventListener('click', () => { reserved = 0; updateInventory(); document.querySelector('#quantity').value = 3; status.textContent = 'Demostración reiniciada. Tienes 5 unidades disponibles para apartar.'; });
document.querySelector('#brief-form').addEventListener('submit', event => { event.preventDefault(); const business = document.querySelector('#business').value.trim(); if (!business) { document.querySelector('#business').setCustomValidity('Describe brevemente tu idea o necesidad.'); document.querySelector('#business').reportValidity(); return; } const challenge = document.querySelector('#challenge').value; const content = `KOI SYSTEMS — IDEA DE PROYECTO\n\nIdea o necesidad: ${business}\nTipo de proyecto: ${challenge}\n\nPara nuestra conversación:\n1. ¿Qué problema queremos resolver?\n2. ¿Quiénes usarán la solución?\n3. ¿Qué funciones son esenciales para la primera versión?\n4. ¿Qué herramientas o datos necesitamos conectar?\n5. ¿Cómo sabremos que el proyecto cumple su objetivo?\n\nDocumento preparado en la landing de KOI Systems. No constituye una propuesta comercial ni un compromiso de alcance.\n`; const url = URL.createObjectURL(new Blob([content], { type: 'text/plain;charset=utf-8' })); const link = document.createElement('a'); link.href = url; link.download = 'KOI-idea-de-proyecto.txt'; document.body.appendChild(link); link.click(); link.remove(); setTimeout(() => URL.revokeObjectURL(url), 1000); document.querySelector('#brief-status').textContent = 'Descripción generada. Puedes compartir el archivo con el equipo de KOI.'; });
document.querySelector('#business').addEventListener('input', event => event.target.setCustomValidity(''));
